def keep_default_reminders(apps, schema_editor):
    """Keep [24, 1] for events that have not started and stored [] (#582).

    The scheduler used to treat [] as [24, 1]. After this change [] disables
    reminders, so rows that got [] from the old model default keep their reminders.
    """
